$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../scripts/modules/Lifecycle.ps1')
. (Join-Path $PSScriptRoot '../scripts/modules/LegacyRecovery.ps1')
function Assert($Condition,$Message){if(-not $Condition){throw $Message}}
$root=Join-Path $PSScriptRoot ('.tmp-legacy-recovery-'+[guid]::NewGuid())
$destination=Join-Path $root ('assistant '+[char]0x4e2d)
New-Item -ItemType Directory -Path (Join-Path $destination 'modules'),(Join-Path $destination 'configs') -Force | Out-Null
$module=Join-Path $destination 'modules/GstarAssistant.grx';[IO.File]::WriteAllText($module,'native fixture bytes, not executable')
$config=Join-Path $destination 'configs/assistant.json';[IO.File]::WriteAllText($config,'{"setting":"original"}')
$custom=Join-Path $destination 'private-drawing.dwg';[IO.File]::WriteAllText($custom,'private fixture drawing, retain')
$target=[pscustomobject]@{family='GstarAssistant';release='R26';path=$destination;payloadRoot=$destination}
$candidate=[pscustomobject]@{schema_version=2;product='GstarAssistant';layout='gstarassistant-v1';version='1.2.3';target_year='2026';files=[pscustomobject]@{'modules/GstarAssistant.grx'=(Get-GdiagFileHash $module);'configs/assistant.json'=(Get-GdiagFileHash $config);'lib/missing.dll'=('A'*64)}}
$before=Get-GdiagTreeHash @(Get-GdiagTree $destination)
$eligible=Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) absent
Assert ($eligible.canOverlay -and $eligible.missingCount -eq 1 -and $eligible.matchingCount -eq 2 -and $eligible.preservationCount -eq 1) 'Safe missing-file overlay was not identified'
Assert ((Get-GdiagTreeHash @(Get-GdiagTree $destination)) -eq $before) 'Assessment modified source'
$public=ConvertTo-GdiagPublic $eligible | ConvertTo-Json -Depth 20
Assert ($public -notmatch 'private-drawing|private fixture|"setting"') 'Private filenames/contents leaked'
[IO.File]::WriteAllText($config,'{"setting":"customer edit"}')
$collision=Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) invalid
Assert (-not $collision.canOverlay -and $collision.collisionCount -eq 1) 'Unknown local config edit permitted overwrite'
Assert (@($collision.observed.files | Where-Object assessment -eq 'collision_requires_preservation_and_migration').Count -eq 1) 'Concrete collision path missing'
[IO.File]::WriteAllText($config,'{"setting":"original"}')
[IO.File]::WriteAllText((Join-Path $destination 'payload-manifest.json'),'{ broken manifest')
$badMetadata=Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) invalid
Assert ($badMetadata.canOverlay -and @($badMetadata.observed.files | Where-Object assessment -eq 'invalid_metadata_preserve_original_before_replacement').Count -eq 1) 'Invalid metadata was not explicitly preserved'
[IO.File]::WriteAllText((Join-Path $destination 'uninstall.exe'),'existing unknown generated bytes')
$generated=Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) invalid
Assert (-not $generated.canOverlay -and $generated.generatedCollisionCount -eq 1) 'Generated uninstaller overwrite was accepted'
$target.payloadRoot=Join-Path $destination 'contents'
$legacy=Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) absent
Assert (-not $legacy.canOverlay -and $legacy.layoutMigrationRequired) 'Legacy contents layout silently migrated'
$target.payloadRoot=Join-Path $root 'another-release'
$refused=$false;try{Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) absent | Out-Null}catch{$refused=$true}
Assert $refused 'Cross-installation registered payload accepted'
$target.payloadRoot=$destination
New-Item -ItemType Directory -Path (Join-Path $destination 'contents/configs') -Force | Out-Null
[IO.File]::WriteAllText((Join-Path $destination 'contents/configs/assistant.json'),'legacy settings must remain private')
$unknownLayout=Get-GdiagLegacyRecoveryAssessment $target $candidate @(Get-GdiagTree $destination) invalid
Assert (-not $unknownLayout.canOverlay -and $unknownLayout.legacyLayoutUnverified) 'Catalog-default path hid legacy migration need'
Write-GdiagJson (Join-Path $root 'acceptance.json') @{status='passed';native='exact file/hash comparison only';vendorExecution='not_run';eligible=(ConvertTo-GdiagPublic $eligible);collision=(ConvertTo-GdiagPublic $collision);legacy=(ConvertTo-GdiagPublic $legacy)}
'PASS legacy recovery: missing/invalid metadata, same-layout missing-file eligibility, exact collision/preservation plan, custom-file privacy, generated file and legacy/root mismatch refusal. Artifacts: '+$root
